function separateDigits(nums) {
  let result = [];
  for (let i = 0; i < nums.length; i++) {
    let value = nums[i];
    const reversed = [];
    while (value > 0) {
      reversed.push(value % 10);
      value = Math.floor(value / 10);
    }
    result = result.concat(reversed.reverse());
  }
  return result;
}

