function generate(rand, size) {
  const pick = () => {
    if (rand() < 0.05) return 100000;
    const length = 1 + Math.floor(rand() * 5);
    const low = length === 1 ? 1 : 10 ** (length - 1);
    const high = 10 ** length - 1;
    if (rand() < 0.2) return low;
    return low + Math.floor(rand() * (high - low + 1));
  };
  const n = size === 'large' ? 1000 : 1 + Math.floor(rand() * 6);
  return [Array.from({ length: n }, pick)];
}
